    insert into public.tools (nombre, protocolo, descripcion) values ($q$FTP$q$, $q$FTP (21/tcp)$q$, $q$File Transfer Protocol. Servicio de transferencia de archivos que corre por defecto en el puerto 21. En enumeracion nos interesa el banner con la version, si permite login anonimo, y el contenido de los directorios accesibles.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sV -p21 -sC -A 10.10.10.10$q$, $q$Escaneo completo del puerto 21. Trae version del servicio, corre los scripts por defecto (incluyendo ftp-anon y ftp-syst) y hace deteccion de OS.$q$),
    (t_id, $q$nmap -sV -p21 --script ftp-anon 10.10.10.10$q$, $q$Corre solo el script ftp-anon para comprobar si el login anonimo esta permitido.$q$),
    (t_id, $q$nmap -p21 --script ftp-* 10.10.10.10$q$, $q$Corre todos los scripts NSE relacionados con FTP contra el objetivo.$q$),
    (t_id, $q$ftp 10.10.10.10$q$, $q$Conexion basica al servidor FTP. Luego pide usuario y contrasena de forma interactiva.$q$),
    (t_id, $q$ftp anonymous@10.10.10.10$q$, $q$Conexion al FTP especificando el usuario anonymous directamente. La contrasena suele quedar vacia.$q$),
    (t_id, $q$nc -nv 10.10.10.10 21$q$, $q$Se conecta al puerto 21 con netcat para leer el banner del servicio de forma cruda.$q$),
    (t_id, $q$telnet 10.10.10.10 21$q$, $q$Conexion cruda al puerto 21 con telnet para capturar el banner.$q$),
    (t_id, $q$openssl s_client -connect 10.10.10.10:21 -starttls ftp$q$, $q$Se conecta a un FTP con TLS (FTPS) para leer el banner y el certificado, util cuando el servicio cifra la sesion.$q$),
    (t_id, $q$ls$q$, $q$Dentro de la sesion FTP, lista el contenido del directorio actual.$q$),
    (t_id, $q$ls -la$q$, $q$Dentro de la sesion FTP, lista todo el contenido incluyendo archivos ocultos y permisos.$q$),
    (t_id, $q$cd <directorio>$q$, $q$Dentro de la sesion FTP, cambia al directorio indicado.$q$),
    (t_id, $q$get <archivo>$q$, $q$Dentro de la sesion FTP, descarga el archivo indicado al directorio local.$q$),
    (t_id, $q$put <archivo>$q$, $q$Dentro de la sesion FTP, sube un archivo local al servidor. Solo funciona si el servidor permite escritura.$q$),
    (t_id, $q$binary$q$, $q$Dentro de la sesion FTP, cambia el modo de transferencia a binario para no corromper archivos que no son texto.$q$),
    (t_id, $q$wget -m --no-passive ftp://anonymous:anonymous@10.10.10.10$q$, $q$Descarga de forma recursiva (mirror) todo el contenido accesible del FTP como usuario anonimo.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Estas enumerando el objetivo 10.10.10.10. Escanea su puerto 21 para traer la version del servicio y correr los scripts por defecto de nmap. Escribe el comando.$q$, array[$q$nmap -sV -p21 -sC -A 10.10.10.10$q$, $q$nmap -sV -sC -p21 -A 10.10.10.10$q$, $q$nmap -sV -p21 -sC 10.10.10.10$q$, $q$nmap -p21 -sV -sC 10.10.10.10$q$, $q$nmap -sC -sV -p21 10.10.10.10$q$]::text[], $q$Necesitas la bandera de version, la de scripts por defecto y limitar el escaneo al puerto 21.$q$, $q$-sV trae la version del servicio, -sC corre los scripts por defecto (entre ellos ftp-anon y ftp-syst), -p21 limita al puerto de FTP y -A agrega deteccion de OS y traceroute. Es el escaneo tipico para empezar a enumerar un FTP.$q$),
    (t_id, $q$Quieres comprobar puntualmente si el FTP de 10.10.10.10 permite login anonimo, corriendo solo ese script de nmap. Escribe el comando.$q$, array[$q$nmap -sV -p21 --script ftp-anon 10.10.10.10$q$, $q$nmap -p21 --script ftp-anon 10.10.10.10$q$, $q$nmap --script ftp-anon -p21 10.10.10.10$q$, $q$nmap -p21 --script=ftp-anon 10.10.10.10$q$]::text[], $q$El script de nmap que revisa el acceso anonimo se llama ftp-anon.$q$, $q$El script ftp-anon intenta un login anonimo y reporta si esta permitido, ademas de listar el directorio si logra entrar. Es mas rapido y silencioso que correr todos los scripts cuando solo te interesa ese dato.$q$),
    (t_id, $q$El FTP de 10.10.10.10 permite acceso anonimo. Conectate al servidor especificando el usuario anonymous directamente en el comando. Escribe el comando.$q$, array[$q$ftp anonymous@10.10.10.10$q$]::text[], $q$El cliente ftp acepta el formato usuario@host igual que ssh.$q$, $q$ftp anonymous@10.10.10.10 abre la conexion ya con el usuario anonymous. Cuando pida contrasena la dejas vacia (o pones anonymous) y entras. Tambien vale conectar con solo 'ftp 10.10.10.10' y escribir anonymous cuando pida el usuario.$q$),
    (t_id, $q$Prefieres conectarte al FTP de 10.10.10.10 sin pasar el usuario en el comando, para que te lo pida de forma interactiva. Escribe el comando de conexion.$q$, array[$q$ftp 10.10.10.10$q$]::text[], $q$Es la forma mas basica de conexion, solo el binario y el destino.$q$, $q$ftp 10.10.10.10 abre la sesion y el servidor pide usuario y contrasena de forma interactiva. Para acceso anonimo escribes anonymous como usuario y dejas la contrasena vacia.$q$),
    (t_id, $q$Ya estas dentro de la sesion FTP y quieres ver todo el contenido del directorio actual, incluyendo archivos ocultos. Escribe el comando.$q$, array[$q$ls -la$q$, $q$ls -al$q$, $q$ls -a -l$q$]::text[], $q$Es el mismo flag que usarias en una shell de Linux para ver ocultos y detalle.$q$, $q$Dentro del FTP, ls -la lista todo con permisos y archivos ocultos. Muchos flags de labs estan en archivos que no aparecen con un ls simple, por eso conviene siempre listar con -la.$q$),
    (t_id, $q$Dentro del FTP encontraste el archivo flag.txt y quieres descargarlo a tu maquina. Escribe el comando.$q$, array[$q$get flag.txt$q$]::text[], $q$El comando para bajar un archivo desde el FTP empieza con get.$q$, $q$get flag.txt descarga el archivo al directorio local desde el que abriste la sesion FTP. Luego lo lees en tu maquina con cat flag.txt.$q$),
    (t_id, $q$Quieres leer el banner crudo del servicio FTP de 10.10.10.10 conectandote al puerto 21 con netcat. Escribe el comando.$q$, array[$q$nc -nv 10.10.10.10 21$q$, $q$nc 10.10.10.10 21$q$]::text[], $q$Usa netcat en modo verboso y sin resolver DNS, apuntando al puerto 21.$q$, $q$nc -nv 10.10.10.10 21 abre una conexion cruda al puerto 21. -n evita resolucion DNS y -v da salida verbosa. El servidor responde con su banner, que muchas veces revela el software y la version exacta del FTP.$q$),
    (t_id, $q$El FTP de 10.10.10.10 corre sobre TLS y quieres leer su banner y certificado. Conectate con openssl haciendo starttls sobre ftp. Escribe el comando.$q$, array[$q$openssl s_client -connect 10.10.10.10:21 -starttls ftp$q$]::text[], $q$Es el cliente s_client de openssl, con -connect al puerto 21 y el -starttls apropiado.$q$, $q$openssl s_client -connect 10.10.10.10:21 -starttls ftp negocia el cifrado sobre el FTP y te deja leer el banner y el certificado. El certificado a veces filtra nombres de host internos y correos utiles para seguir enumerando.$q$),
    (t_id, $q$Quieres descargar de forma recursiva todo el contenido accesible del FTP anonimo de 10.10.10.10, en un solo comando. Escribe el comando.$q$, array[$q$wget -m --no-passive ftp://anonymous:anonymous@10.10.10.10$q$, $q$wget -m ftp://anonymous:anonymous@10.10.10.10$q$]::text[], $q$Usa wget en modo mirror (-m) con credenciales anonymous embebidas en la URL del ftp.$q$, $q$wget -m --no-passive ftp://anonymous:anonymous@10.10.10.10 hace un mirror de todo el arbol de directorios accesible. Es util cuando hay muchos archivos y no quieres bajarlos uno por uno. --no-passive fuerza modo activo, que a veces es necesario segun la config del servidor.$q$);
    insert into public.tools (nombre, protocolo, descripcion) values ($q$SMB$q$, $q$SMB (139/445 tcp)$q$, $q$Server Message Block. Protocolo de comparticion de archivos, impresoras y recursos en red, muy comun en entornos Windows y en servidores Samba. En enumeracion buscamos shares accesibles, sesiones nulas, usuarios, grupos e informacion del dominio. Herramientas clave: smbclient, rpcclient, smbmap, crackmapexec y enum4linux-ng.$q$) returning id into t_id;
  insert into public.commands (tool_id, comando, descripcion) values
    (t_id, $q$nmap -sV -sC -p139,445 10.10.10.10$q$, $q$Escaneo de version y scripts por defecto sobre los puertos de SMB. Trae el banner y datos basicos del servicio.$q$),
    (t_id, $q$nmap -p445 --script smb-os-discovery 10.10.10.10$q$, $q$Descubre el sistema operativo, nombre de equipo y dominio a traves de SMB.$q$),
    (t_id, $q$smbclient -N -L 10.10.10.10$q$, $q$Lista los shares del servidor usando sesion nula (-N sin contrasena, -L para listar).$q$),
    (t_id, $q$smbclient -L 10.10.10.10 -U <usuario>$q$, $q$Lista los shares autenticandose con un usuario valido.$q$),
    (t_id, $q$smbclient //10.10.10.10/<share>$q$, $q$Se conecta a un share especifico para navegarlo.$q$),
    (t_id, $q$smbclient //10.10.10.10/<share> -N$q$, $q$Se conecta a un share especifico usando sesion nula, sin credenciales.$q$),
    (t_id, $q$smbmap -H 10.10.10.10$q$, $q$Enumera los shares del servidor y muestra los permisos de acceso (lectura/escritura) sobre cada uno.$q$),
    (t_id, $q$smbmap -H 10.10.10.10 -u <usuario> -p <contrasena>$q$, $q$Enumera shares y permisos autenticandose con credenciales.$q$),
    (t_id, $q$rpcclient -U "" 10.10.10.10$q$, $q$Abre una sesion RPC con usuario vacio (sesion nula) para interactuar con el servicio y enumerar informacion.$q$),
    (t_id, $q$crackmapexec smb 10.10.10.10 --shares -u '' -p ''$q$, $q$Enumera los shares usando autenticacion de sesion nula con crackmapexec.$q$),
    (t_id, $q$enum4linux-ng.py 10.10.10.10 -A$q$, $q$Enumeracion automatica y completa de SMB: usuarios, grupos, shares, politicas de contrasena e informacion del sistema.$q$);
  insert into public.exercises (tool_id, enunciado, respuestas_aceptadas, pista, explicacion) values
    (t_id, $q$Quieres listar todos los shares del servidor SMB 10.10.10.10 usando una sesion nula, sin credenciales, con smbclient. Escribe el comando.$q$, array[$q$smbclient -L 10.10.10.10 -N$q$, $q$smbclient -N -L 10.10.10.10$q$, $q$smbclient -L //10.10.10.10 -N$q$, $q$smbclient -N -L //10.10.10.10$q$, $q$smbclient -L //10.10.10.10/ -N$q$]::text[], $q$El flag -N usa sesion nula y el flag -L lista los shares.$q$, $q$smbclient -L 10.10.10.10 -N pide la lista de shares sin autenticarse. -L le dice que solo liste y -N fuerza sesion nula (sin contrasena). El // solo hace falta cuando te vas a conectar a un share concreto (smbclient //10.10.10.10/notes). Es de lo primero que se prueba, porque muchos servidores exponen shares por sesion nula.$q$),
    (t_id, $q$En 10.10.10.10 descubriste un share llamado 'notes' y quieres conectarte a el usando sesion nula para navegarlo. Escribe el comando.$q$, array[$q$smbclient //10.10.10.10/notes -N$q$, $q$smbclient -N //10.10.10.10/notes$q$]::text[], $q$Es smbclient apuntando directo al share, con el flag de sesion nula.$q$, $q$smbclient //10.10.10.10/notes -N te conecta al share 'notes' sin credenciales. Una vez dentro navegas con ls, cd y descargas con get, igual que en FTP.$q$),
    (t_id, $q$Quieres enumerar los shares de 10.10.10.10 y ver que permisos de lectura o escritura tienes sobre cada uno, con smbmap. Escribe el comando.$q$, array[$q$smbmap -H 10.10.10.10$q$]::text[], $q$smbmap usa el flag -H para indicar el host.$q$, $q$smbmap -H 10.10.10.10 lista los shares junto con los permisos efectivos (READ, WRITE, NO ACCESS). Es mas util que smbclient -L cuando quieres saber de inmediato donde puedes escribir o leer, no solo que shares existen.$q$),
    (t_id, $q$Quieres abrir una sesion RPC contra 10.10.10.10 usando una sesion nula (usuario vacio) para enumerar informacion del dominio. Escribe el comando.$q$, array[$q$rpcclient -U "" 10.10.10.10$q$, $q$rpcclient -U '' 10.10.10.10$q$, $q$rpcclient -U "" -N 10.10.10.10$q$]::text[], $q$Es rpcclient con el flag -U y un usuario entre comillas vacio.$q$, $q$rpcclient -U "" 10.10.10.10 abre una sesion RPC nula. El usuario vacio entre comillas es lo que produce la sesion nula. Ya dentro puedes correr comandos como enumdomusers, querydominfo o netshareenumall para sacar usuarios, info del dominio y shares.$q$),
    (t_id, $q$Ya estas dentro de rpcclient y quieres enumerar todos los usuarios del dominio. Escribe el comando.$q$, array[$q$enumdomusers$q$]::text[], $q$El comando dentro de rpcclient empieza con enumdom y termina en el plural de usuario en ingles.$q$, $q$enumdomusers lista todas las cuentas de usuario del dominio con su RID. Es una de las razones principales para entrar a rpcclient, porque te da la lista de usuarios que luego puedes usar para ataques de password o para seguir enumerando.$q$),
    (t_id, $q$Dentro de rpcclient quieres ver la informacion general del dominio (nombre, politicas, cantidad de usuarios). Escribe el comando.$q$, array[$q$querydominfo$q$]::text[], $q$El comando junta las palabras query, dom e info.$q$, $q$querydominfo devuelve informacion del dominio o workgroup: nombre del dominio, servidor, total de usuarios y politicas basicas. Ayuda a entender si estas frente a un dominio real o un workgroup local.$q$),
    (t_id, $q$Dentro de rpcclient quieres listar todos los shares disponibles en el servidor. Escribe el comando.$q$, array[$q$netshareenumall$q$, $q$netshareenum$q$]::text[], $q$El comando empieza con netshareenum.$q$, $q$netshareenumall enumera todos los shares del servidor, incluyendo algunos administrativos que no siempre aparecen con smbclient -L. Es util contrastar esta salida con la de otras herramientas para no perderte ningun share.$q$),
    (t_id, $q$Quieres correr una enumeracion completa y automatica de SMB contra 10.10.10.10 (usuarios, grupos, shares, politicas) con enum4linux-ng. Escribe el comando.$q$, array[$q$enum4linux-ng.py 10.10.10.10 -A$q$, $q$enum4linux-ng.py -A 10.10.10.10$q$, $q$./enum4linux-ng.py 10.10.10.10 -A$q$, $q$enum4linux-ng 10.10.10.10 -A$q$]::text[], $q$Es el script enum4linux-ng con el flag -A de enumeracion agresiva o completa.$q$, $q$enum4linux-ng.py 10.10.10.10 -A hace la pasada completa: junta lo que sacarian rpcclient, smbclient y nmblookup en una sola corrida y te devuelve usuarios, grupos, shares, politicas de contrasena e info del sistema. Es un buen primer barrido antes de ir a mano con rpcclient.$q$);
